package com.afterglow.player;
import android.app.*;import android.widget.*;import java.util.*;
/** Library filters are a view; playback identity and stored library order never change. */
final class LibraryPanel {
 final MainActivity a;String playlist=null;boolean favorites=false;
 LibraryPanel(MainActivity a){this.a=a;}
 List<Integer> indices(){List<Track> source=playlist==null?new ArrayList<>(a.service.queue):a.service.collections.members(playlist,a.service.queue);source.removeIf(t->favorites&&!t.favorite);int sort=a.prefs.getInt("librarySort",0);Comparator<Track> title=Comparator.comparing(t->t.title,String.CASE_INSENSITIVE_ORDER);if(sort==1)source.sort(title);if(sort==2)source.sort(title.reversed());if(sort==3)source.sort(Comparator.comparing((Track t)->t.artist,String.CASE_INSENSITIVE_ORDER).thenComparing(title));if(sort==4)Collections.shuffle(source,new Random(a.prefs.getLong("shuffleSeed",0)));if(sort==5){Set<Track> ready=new HashSet<>();for(Track t:source)if("local".equals(t.kind)||AudioCache.find(a,t.uri)!=null)ready.add(t);source.sort(Comparator.comparingInt((Track t)->ready.contains(t)?0:1).thenComparing(title));}String query=a.songQuery.trim().toLowerCase(Locale.ROOT);List<Integer> result=new ArrayList<>();for(Track t:source)if((t.title+" "+t.artist).toLowerCase(Locale.ROOT).contains(query))result.add(a.service.queue.indexOf(t));return result;}
 List<Track> visible(){ArrayList<Track> songs=new ArrayList<>();for(int i:indices())songs.add(a.service.queue.get(i));return songs;}
 String label(){return playlist!=null?playlist:favorites?"Favourites":"All songs";}
 void controls(LinearLayout body){LinearLayout filters=a.row();a.addSpacedControl(filters,a.button("All songs",()->{playlist=null;favorites=false;a.renderSongs();}));a.addSpacedControl(filters,a.button("♥ Favourites",()->{playlist=null;favorites=true;a.renderSongs();}));a.addSpacedControl(filters,a.button("Playlists",this::playlists));body.addView(filters);LinearLayout actions=a.row();a.addSpacedControl(actions,a.button("Sort",this::sort));a.addSpacedControl(actions,a.button("Play list",()->play(false)));a.addSpacedControl(actions,a.button("Shuffle play",()->play(true)));body.addView(actions);}
 void play(boolean shuffle){List<Track> tracks=visible();if(tracks.isEmpty()){a.toast("No songs in this view");return;}if(shuffle){a.prefs.edit().putInt("librarySort",4).putLong("shuffleSeed",System.nanoTime()).apply();tracks=visible();a.renderSongs();}a.service.playSequence(tracks,false);a.permissionsForPlayback();a.toast("Playing "+tracks.size()+" songs · next 10 prepare in the queue");}
 void sort(){String[] names={"Added / playlist order","Title A–Z","Title Z–A","Artist A–Z","Shuffled order","Cached / local ready first"};new AlertDialog.Builder(a).setTitle("Sort songs").setSingleChoiceItems(names,a.prefs.getInt("librarySort",0),(d,n)->{a.prefs.edit().putInt("librarySort",n).putLong("shuffleSeed",System.nanoTime()).apply();a.renderSongs();d.dismiss();}).setNegativeButton("Cancel",null).show();}
 void playlists(){ArrayList<String> names=new ArrayList<>(a.service.collections.playlists.keySet());names.add("+ Create playlist");new AlertDialog.Builder(a).setTitle("Your playlists").setItems(names.toArray(new String[0]),(d,n)->{if(n==names.size()-1)create(null);else actions(names.get(n));}).setNegativeButton("Close",null).show();}
 void create(Track initial){EditText input=new EditText(a);input.setSingleLine();input.setHint("Playlist name");AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Create playlist").setView(input).setPositiveButton("Create",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String name=input.getText().toString().trim();if(!a.service.collections.create(name)){input.setError("Use a unique name, 1–80 characters");return;}if(initial!=null)a.service.collections.add(name,initial);a.service.save();dialog.dismiss();if(initial==null)edit(name);else a.toast("Added to "+name);}));dialog.show();}
 void add(Track t){ArrayList<String> names=new ArrayList<>(a.service.collections.playlists.keySet());names.add("+ New playlist");new AlertDialog.Builder(a).setTitle("Add to playlist").setItems(names.toArray(new String[0]),(d,n)->{if(n==names.size()-1)create(t);else{a.service.collections.add(names.get(n),t);a.service.save();a.toast("Added to "+names.get(n));}}).show();}
 void actions(String name){new AlertDialog.Builder(a).setTitle(name).setItems(new String[]{"Open playlist","Play","Shuffle play","Edit songs","Rename","Delete playlist"},(d,n)->{if(n<3){playlist=name;favorites=false;a.renderSongs();if(n>0)play(n==2);}else if(n==3)edit(name);else if(n==4)rename(name);else new AlertDialog.Builder(a).setTitle("Delete playlist?").setMessage("Songs and cached audio stay in your library.").setPositiveButton("Delete",(x,w)->{a.service.collections.playlists.remove(name);if(name.equals(playlist))playlist=null;a.service.save();a.renderSongs();}).setNegativeButton("Cancel",null).show();}).show();}
 void edit(String name){List<Track> tracks=new ArrayList<>(a.service.queue);String[] labels=new String[tracks.size()];boolean[] selected=new boolean[tracks.size()];for(int i=0;i<tracks.size();i++){Track t=tracks.get(i);labels[i]=t.title+" · "+t.artist;selected[i]=a.service.collections.playlists.get(name).contains(t.id);}new AlertDialog.Builder(a).setTitle("Songs in "+name).setMultiChoiceItems(labels,selected,(d,n,on)->selected[n]=on).setPositiveButton("Save",(d,w)->{ArrayList<String> ids=a.service.collections.playlists.get(name);if(ids==null)return;ids.clear();for(int i=0;i<tracks.size();i++)if(selected[i]&&a.service.queue.contains(tracks.get(i)))ids.add(tracks.get(i).id);a.service.save();playlist=name;favorites=false;a.renderSongs();}).setNegativeButton("Cancel",null).show();}
 void rename(String old){EditText input=new EditText(a);input.setSingleLine();input.setText(old);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Rename playlist").setView(input).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String name=input.getText().toString().trim();if(name.equals(old)){dialog.dismiss();return;}if(!a.service.collections.create(name)){input.setError("Use a unique name, 1–80 characters");return;}a.service.collections.playlists.put(name,a.service.collections.playlists.remove(old));if(old.equals(playlist))playlist=name;a.service.save();a.renderSongs();dialog.dismiss();}));dialog.show();}
}
